package com.example.domain.model.i18n

internal object DuaTa1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("தூக்கத்திலிருந்து எழும்போது", "எங்களை மரணிக்கச் செய்த (தூங்க வைத்த) பின் உயிர்ப்பித்த அல்லாஹ்வுக்கே எல்லாப் புகழும்; அவனிடமே மீண்டும் எழுப்பப்பட்டுச் செல்ல வேண்டும்.", "தூக்கத்திலிருந்து எழுந்தவுடன் அல்லாஹ்வுக்கு நன்றி செலுத்த.", "நபி ﷺ தூங்கி எழுந்ததும் இந்த துஆவை ஓதுவார்கள் — நாளின் தொடக்கம் நன்றியுடனும் மறுமை நினைவுடனும்."),
        "dua_leaving_home" to DuaText("வீட்டிலிருந்து வெளியேறும்போது", "அல்லாஹ்வின் பெயரால்; நான் அல்லாஹ்வின் மீது நம்பிக்கை வைத்தேன். அல்லாஹ்வைக் கொண்டே அன்றி எந்த ஆற்றலும் இல்லை, எந்த சக்தியும் இல்லை.", "வீட்டை விட்டு வெளியே அடி எடுத்து வைக்கும்போது அல்லாஹ்வின் பாதுகாப்புக்காக.", "வானவர்கள் கூறுவார்கள்: 'நீ நேர்வழி காட்டப்பட்டாய், உனக்குப் போதுமானது செய்யப்பட்டது, நீ பாதுகாக்கப்பட்டாய்', ஷைத்தான் விலகிச் சென்றுவிடுவான்."),
        "dua_anxiety_distress" to DuaText("கவலை மற்றும் துக்கத்திலிருந்து விடுதலை", "யா அல்லாஹ்! கவலை மற்றும் துக்கத்திலிருந்தும், இயலாமை மற்றும் சோம்பலிலிருந்தும், கஞ்சத்தனம் மற்றும் கோழைத்தனத்திலிருந்தும், கடன் சுமை மற்றும் மனிதர்களின் ஆதிக்கத்திலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "துக்கம், கவலை, கடன் சுமை மற்றும் மன உளைச்சலின் போது.", "நபி ﷺ இந்த துஆவை அதிகமாகக் கேட்பார்கள் — துக்கம், சோம்பல் மற்றும் கடன் கவலையிலிருந்து பாதுகாப்பு."),
        "dua_sayyidul_istighfar" to DuaText("ஸய்யிதுல் இஸ்திஃக்ஃபார்", "யா அல்லாஹ்! நீயே என் இறைவன், உன்னைத் தவிர வணக்கத்திற்குரியவன் இல்லை. நீ என்னைப் படைத்தாய், நான் உன் அடியான்; என்னால் இயன்றவரை உன் உடன்படிக்கையிலும் வாக்குறுதியிலும் இருக்கிறேன். நான் செய்தவற்றின் தீங்கிலிருந்து உன்னிடம் பாதுகாப்புத் தேடுகிறேன். என் மீதுள்ள உன் அருட்கொடைகளை ஒப்புக்கொள்கிறேன், என் பாவத்தையும் ஒப்புக்கொள்கிறேன்; எனவே என்னை மன்னிப்பாயாக, ஏனெனில் உன்னைத் தவிர பாவங்களை மன்னிப்பவர் யாருமில்லை.", "காலையும் மாலையும் — நபி ﷺ கற்றுத்தந்த மிகச் சிறந்த பாவமன்னிப்பு துஆ.", "உறுதியான நம்பிக்கையுடன் மாலையில் ஓதி அன்றிரவே இறந்தவர் சொர்க்கம் செல்வார்; காலையில் ஓதினாலும் இதே சிறப்பு."),
        "dua_parents" to DuaText("பெற்றோருக்கான துஆ", "என் இறைவா! நான் சிறுவனாக இருந்தபோது அவர்கள் என்னை வளர்த்தது போல் அவ்விருவர் மீதும் கருணை காட்டுவாயாக.", "பெற்றோருக்கான குர்ஆன் துஆ — குழந்தைப் பருவ வளர்ப்புக்குப் பகரமாக.", "அல்லாஹ்வே பெற்றோருக்காக இந்த துஆவைக் கேட்கும்படி கட்டளையிட்டான்."),
        "dua_entering_mosque" to DuaText("பள்ளிவாசலில் நுழையும்போது", "யா அல்லாஹ்! எனக்காக உன் அருளின் வாசல்களைத் திறப்பாயாக.", "வலது காலை வைத்து பள்ளிவாசலில் நுழையும்போது.", "பள்ளிவாசலில் நுழையும்போது இந்த துஆவை ஓதுமாறு நபி ﷺ கற்றுத்தந்தார்கள்."),
        "dua_morning_asbahna" to DuaText("காலை திக்ர்", "நாங்கள் காலையை அடைந்தோம், ஆட்சி முழுவதும் அல்லாஹ்வுக்காகவே காலையை அடைந்தது. எல்லாப் புகழும் அல்லாஹ்வுக்கே. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணை இல்லை. ஆட்சி அவனுக்கே, புகழும் அவனுக்கே, அவன் எல்லாவற்றின் மீதும் ஆற்றலுடையவன்.", "காலையில் ஓதப்படும் சுன்னத்தான துஆ.", "நாள் அல்லாஹ்வின் ஆட்சியையும் ஏகத்துவத்தையும் ஒப்புக்கொள்வதுடன் தொடங்குகிறது."),
        "dua_evening_amsayna" to DuaText("மாலை திக்ர்", "நாங்கள் மாலையை அடைந்தோம், ஆட்சி முழுவதும் அல்லாஹ்வுக்காகவே மாலையை அடைந்தது. எல்லாப் புகழும் அல்லாஹ்வுக்கே. அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணை இல்லை. ஆட்சி அவனுக்கே, புகழும் அவனுக்கே, அவன் எல்லாவற்றின் மீதும் ஆற்றலுடையவன்.", "மாலையில் ஓதப்படும் சுன்னத்தான துஆ.", "இரவு அல்லாஹ்வின் ஆட்சியையும் ஏகத்துவத்தையும் ஒப்புக்கொள்வதுடன் தொடங்குகிறது."),
        "dua_bismillah_la_yadurru" to DuaText("எல்லாத் தீங்கிலிருந்தும் பாதுகாப்பு", "அல்லாஹ்வின் பெயரால்; அவனுடைய பெயருடன் பூமியிலோ வானத்திலோ எதுவும் தீங்கிழைக்க முடியாது, அவன் செவியுறுபவன், அறிந்தவன்.", "காலையும் மாலையும் மும்முறை.", "காலை மாலை மும்முறை இதை ஓதுபவருக்கு எதுவும் தீங்கிழைக்காது."),
        "dua_raditu_billahi" to DuaText("அல்லாஹ்வை இறைவனாக ஏற்றுத் திருப்தி", "அல்லாஹ்வை இறைவனாகவும், இஸ்லாத்தை மார்க்கமாகவும், முஹம்மத் ﷺ அவர்களை நபியாகவும் ஏற்று நான் திருப்தியடைந்தேன்.", "காலையும் மாலையும் மும்முறை.", "மறுமை நாளில் அவரைத் திருப்திப்படுத்துவது அல்லாஹ்வின் மீது அவருக்குரிய உரிமையாகிறது."),
        "dua_hasbiyallah" to DuaText("ஹஸ்பியல்லாஹ் (அல்லாஹ் போதுமானவன்)", "எனக்கு அல்லாஹ் போதுமானவன், அவனைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் மீதே நம்பிக்கை வைத்தேன், அவன் மகத்தான அர்ஷின் இறைவன்.", "காலையும் மாலையும் ஏழு முறை.", "குர்ஆன் வசனம்; இம்மை மறுமைக் கவலைகளில் அல்லாஹ் போதுமானவனாகிறான்."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("ஸுப்ஹானல்லாஹி வ பிஹம்திஹீ", "அல்லாஹ் தூயவன், எல்லாப் புகழும் அவனுக்கே.", "நாளொன்றுக்கு நூறு முறை.", "நாளொன்றுக்கு நூறு முறை கூறுபவரின் பாவங்கள் கடல் நுரை அளவு இருந்தாலும் மன்னிக்கப்படும்."),
        "dua_tahleel_100" to DuaText("லா இலாஹ இல்லல்லாஹு வஹ்தஹூ", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணை இல்லை. ஆட்சியும் புகழும் அவனுக்கே, அவன் எல்லாவற்றின் மீதும் ஆற்றலுடையவன்.", "நாளொன்றுக்கு நூறு முறை ஓதுவதன் பெரும் சிறப்பு.", "பத்து அடிமைகளை விடுதலை செய்த நன்மை, நூறு நன்மைகள், நூறு பாவங்கள் மன்னிப்பு, மாலை வரை ஷைத்தானிடமிருந்து பாதுகாப்பு."),
        "dua_leaving_mosque" to DuaText("பள்ளிவாசலிலிருந்து வெளியேறும்போது", "யா அல்லாஹ்! உன் அருளை உன்னிடம் கேட்கிறேன்.", "இடது காலை வெளியே வைத்து பள்ளிவாசலிலிருந்து வெளியேறும்போது.", "பள்ளிவாசலிலிருந்து வெளியேறும்போது அல்லாஹ்வின் அருளையும் வாழ்வாதாரத்தையும் வேண்டுதல்."),
        "dua_after_adhan" to DuaText("பாங்குக்குப் பின்", "யா அல்லாஹ்! இந்தப் பரிபூரண அழைப்பு மற்றும் நிலைநாட்டப்படவுள்ள தொழுகையின் இறைவனே! முஹம்மத் ﷺ அவர்களுக்கு வஸீலாவையும் சிறப்பையும் வழங்குவாயாக, நீ அவர்களுக்கு வாக்களித்த புகழப்பட்ட இடத்திற்கு அவர்களை எழுப்புவாயாக.", "பாங்கு முடிந்த பின்.", "இதை ஓதுபவருக்கு மறுமை நாளில் நபி ﷺ அவர்களின் பரிந்துரை உறுதியாகிறது."),
        "dua_after_salah_istighfar" to DuaText("கடமையான தொழுகைக்குப் பின்", "அல்லாஹ்விடம் பாவமன்னிப்புக் கோருகிறேன் (3 முறை). யா அல்லாஹ்! நீயே ஸலாம், உன்னிடமிருந்தே அமைதி, மகத்துவமும் கண்ணியமும் உடையவனே! நீ பாக்கியமிக்கவன்.", "ஸலாம் கொடுத்தவுடன்.", "நபி ﷺ ஒவ்வொரு கடமையான தொழுகைக்குப் பின்னும் இதை ஓதுவார்கள்."),
        "dua_after_salah_help_dhikr" to DuaText("உன்னை நினைவுகூர எனக்கு உதவு", "யா அல்லாஹ்! உன்னை நினைவுகூரவும், உனக்கு நன்றி செலுத்தவும், உன்னை அழகிய முறையில் வணங்கவும் எனக்கு உதவுவாயாக.", "ஒவ்வொரு தொழுகைக்குப் பின்னும் — நபி ﷺ முஆத் (ரலி) அவர்களுக்கு அறிவுறுத்தினார்கள்.", "நபி ﷺ அவர்களின் சிறப்பு அறிவுரை — வணக்கத்தில் அழகும் நிலைத்தன்மையும்."),
        "dua_ayatul_kursi" to DuaText("தொழுகைக்குப் பின் ஆயத்துல் குர்ஸி", "அல்லாஹ் — அவனைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் என்றும் உயிருடன் இருப்பவன், அனைத்தையும் நிலைநிறுத்துபவன். சிறு தூக்கமோ ஆழ்ந்த தூக்கமோ அவனைப் பிடிக்காது. வானங்களிலும் பூமியிலும் உள்ளவை அனைத்தும் அவனுக்கே உரியவை. அவனுடைய அனுமதியின்றி அவனிடம் யார் பரிந்துரை செய்ய முடியும்? அவர்களுக்கு முன்னும் பின்னும் உள்ளதை அவன் அறிவான்; அவன் நாடியதைத் தவிர அவனுடைய அறிவில் எதையும் அவர்கள் சூழ்ந்தறிய முடியாது. அவனுடைய குர்ஸி வானங்களையும் பூமியையும் சூழ்ந்துள்ளது; அவ்விரண்டையும் காப்பது அவனுக்குச் சோர்வளிக்காது; அவன் மிக உயர்ந்தவன், மகத்தானவன்.", "ஒவ்வொரு கடமையான தொழுகைக்குப் பின்னும் தூங்குவதற்கு முன்பும்.", "ஒவ்வொரு கடமையான தொழுகைக்குப் பின் ஓதுபவருக்கும் சொர்க்கத்திற்கும் இடையே மரணம் மட்டுமே தடை; தூங்கும் முன் ஓதினால் காலை வரை பாதுகாப்பு."),
        "dua_before_sleep" to DuaText("தூங்குவதற்கு முன்", "யா அல்லாஹ்! உன் பெயரால் நான் மரணிக்கிறேன் (தூங்குகிறேன்), உயிர் பெறுகிறேன் (விழிக்கிறேன்).", "படுக்கையில் படுத்த பின்.", "நபி ﷺ தூங்கும் முன் இந்த துஆவை ஓதுவார்கள்."),
        "dua_sleep_tasbeeh" to DuaText("தூங்கும் முன் தஸ்பீஹ் ஃபாத்திமா", "அல்லாஹ் தூயவன் (33), எல்லாப் புகழும் அல்லாஹ்வுக்கே (33), அல்லாஹ் மிகப் பெரியவன் (34).", "தூங்கும் முன் — நபி ﷺ ஃபாத்திமா, அலீ (ரலி) அவர்களுக்குக் கற்றுத்தந்தார்கள்.", "இது உங்களுக்கு ஒரு பணியாளரை விடச் சிறந்தது என நபி ﷺ கூறினார்கள்."),
        "dua_sleep_qina_adhab" to DuaText("வேதனையிலிருந்து பாதுகாப்பு", "யா அல்லாஹ்! நீ உன் அடியார்களை எழுப்பும் நாளில் உன் வேதனையிலிருந்து என்னைக் காப்பாயாக.", "வலது கையைக் கன்னத்தின் கீழ் வைத்து மும்முறை.", "தூக்கத்தை மரண நினைவாகவும் மறுமைத் தயாரிப்பாகவும் ஆக்குகிறது."),
        "dua_bad_dream" to DuaText("கெட்ட கனவு கண்டால்", "விரட்டப்பட்ட ஷைத்தானிடமிருந்து அல்லாஹ்விடம் பாதுகாப்புத் தேடுகிறேன்.", "கெட்ட கனவு கண்டால்: இடது பக்கம் மூன்று முறை லேசாகத் துப்பி, பின் பக்கம் மாறிப் படுங்கள்.", "கெட்ட கனவு தீங்கிழைக்காது; யாரிடமும் சொல்லாதீர்கள்."),
        "dua_yunus" to DuaText("யூனுஸ் (அலை) அவர்களின் துஆ", "உன்னைத் தவிர வணக்கத்திற்குரியவன் இல்லை, நீ தூயவன், நிச்சயமாக நான் அநியாயக்காரர்களில் ஒருவனாக இருந்தேன்.", "மீன் வயிற்றில் யூனுஸ் (அலை) அவர்களின் துஆ — ஒவ்வொரு துன்பத்திலும்.", "எந்த முஸ்லிம் எந்த விஷயத்திலும் இந்த துஆவைக் கேட்டாலும் அல்லாஹ் அதை ஏற்றுக்கொள்கிறான்."),
        "dua_karb" to DuaText("கடுமையான துன்பத்தின் துஆ", "மகத்தானவனும் சகிப்புத்தன்மை உடையவனுமான அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை. மகத்தான அர்ஷின் இறைவனான அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை. வானங்களின் இறைவனும், பூமியின் இறைவனும், கண்ணியமான அர்ஷின் இறைவனுமான அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை.", "கடுமையான துன்பம் மற்றும் சிரமத்தின் போது.", "நபி ﷺ துன்பத்தின் போது இந்த துஆவை ஓதுவார்கள்."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("யா ஹய்யு யா கய்யூம்", "என்றும் உயிருள்ளவனே, அனைத்தையும் நிலைநிறுத்துபவனே! உன் அருளைக் கொண்டு உதவி தேடுகிறேன்.", "ஒரு விஷயம் மிகவும் பாரமாகும்போது.", "ஏதேனும் விஷயம் நபி ﷺ அவர்களைக் கவலைப்படுத்தினால் இதை ஓதுவார்கள்."),
        "dua_hasbunallah" to DuaText("ஹஸ்புனல்லாஹு வ நிஃமல் வகீல்", "எங்களுக்கு அல்லாஹ் போதுமானவன், அவன் சிறந்த பொறுப்பாளன்.", "எதிரியின் அச்சம் அல்லது பெரிய ஆபத்தின் போது.", "இப்ராஹீம் (அலை) நெருப்பில் எறியப்பட்டபோதும், நபி ﷺ ஆபத்தின் போதும் இதைக் கூறினார்கள்."),
        "dua_entering_home" to DuaText("வீட்டில் நுழையும்போது", "அல்லாஹ்வின் பெயரால்.", "வீட்டில் நுழையும்போது அல்லாஹ்வின் பெயரைக் கூறி ஸலாம் சொல்லுங்கள்.", "வீட்டில் நுழையும்போதும் உண்ணும்போதும் அல்லாஹ்வை நினைவுகூர்ந்தால் ஷைத்தான் கூறுவான்: உங்களுக்கு இங்கு தங்க இடமும் இல்லை, உணவும் இல்லை."),
        "dua_travel" to DuaText("பயண (வாகன) துஆ", "இதை எங்களுக்கு வசப்படுத்தித் தந்தவன் தூயவன்; நாங்கள் இதைக் கட்டுப்படுத்தும் சக்தி பெற்றிருக்கவில்லை; நிச்சயமாக நாங்கள் எங்கள் இறைவனிடம் திரும்பிச் செல்பவர்கள்.", "வாகனத்தில் அமர்ந்து மூன்று முறை அல்லாஹு அக்பர் கூறிய பின்.", "பயணத்தின் சுன்னத்தான துஆ — பாதுகாப்புக்கும் பரக்கத்திற்கும்."),
        "dua_entering_market" to DuaText("சந்தையில் நுழையும்போது", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணை இல்லை. ஆட்சியும் புகழும் அவனுக்கே. அவனே உயிர்ப்பிக்கிறான், மரணிக்கச் செய்கிறான்; அவன் என்றும் உயிருடன் இருப்பவன், ஒருபோதும் மரணிக்க மாட்டான். நன்மை அவன் கையிலேயே உள்ளது, அவன் எல்லாவற்றின் மீதும் ஆற்றலுடையவன்.", "சந்தையில் நுழையும்போது.", "ஹதீஸில் இதன் பெரும் சிறப்பு கூறப்பட்டுள்ளது (லட்சக்கணக்கான நன்மைகள்)."),
        "dua_adam_forgiveness" to DuaText("ஆதம் (அலை) அவர்களின் துஆ", "எங்கள் இறைவா! நாங்கள் எங்களுக்கே அநீதி இழைத்துக்கொண்டோம்; நீ எங்களை மன்னித்து எங்கள் மீது கருணை காட்டாவிட்டால் நிச்சயமாக நாங்கள் நஷ்டமடைந்தவர்களில் ஆகிவிடுவோம்.", "ஆதம், ஹவ்வா (அலை) அவர்களின் பாவமன்னிப்பு துஆ.", "மனிதகுலத்தின் முதல் பாவமன்னிப்பு — அல்லாஹ் அதை ஏற்றுக்கொண்டான்."),
        "dua_abu_bakr" to DuaText("அபூபக்ர் (ரலி) அவர்களுக்குக் கற்றுத்தந்த துஆ", "யா அல்லாஹ்! நான் எனக்கே அதிகம் அநீதி இழைத்துக்கொண்டேன்; உன்னைத் தவிர பாவங்களை மன்னிப்பவர் யாருமில்லை; எனவே உன்னிடமிருந்து எனக்கு மன்னிப்பை வழங்கி என் மீது கருணை காட்டுவாயாக; நிச்சயமாக நீ மன்னிப்பவன், கருணையாளன்.", "தொழுகையில் (அத்தஹிய்யாத்துக்குப் பின்) ஓத நபி ﷺ அபூபக்ர் ஸித்தீக் (ரலி) அவர்களுக்குக் கற்றுத்தந்தார்கள்.", "தொழுகையின் இறுதியில் ஓதும் சுன்னத்தான துஆ."),
        "dua_astaghfirullah_atubu" to DuaText("தினசரி இஸ்திஃக்ஃபார்", "அல்லாஹ்விடம் பாவமன்னிப்புக் கோருகிறேன், அவனிடமே மீள்கிறேன்.", "நபி ﷺ நாளொன்றுக்கு எழுபது முறைக்கு மேல் பாவமன்னிப்புக் கோருவார்கள்.", "நபி ﷺ கூறினார்கள்: நான் நாளொன்றுக்கு எழுபது முறைக்கு மேல் அல்லாஹ்விடம் பாவமன்னிப்புக் கோரி தவ்பா செய்கிறேன்."),
        "dua_laylatul_qadr" to DuaText("லைலத்துல் கத்ர் துஆ", "யா அல்லாஹ்! நீ அதிகம் மன்னிப்பவன், மன்னிப்பதை விரும்புகிறாய்; எனவே என்னை மன்னிப்பாயாக.", "ஆயிஷா (ரலி) அவர்களுக்கு லைலத்துல் கத்ருக்காகக் கற்றுத்தரப்பட்டது.", "ரமழானின் இறுதி இரவுகள் மற்றும் லைலத்துல் கத்ரின் சிறப்பு துஆ."),
        "dua_family_coolness" to DuaText("கண் குளிர்ச்சி (வாழ்க்கைத்துணை, பிள்ளைகள்)", "எங்கள் இறைவா! எங்கள் வாழ்க்கைத் துணைகளிலிருந்தும் பிள்ளைகளிலிருந்தும் எங்களுக்குக் கண் குளிர்ச்சியை வழங்குவாயாக, இறையச்சமுடையோருக்கு எங்களைத் தலைவர்களாக ஆக்குவாயாக.", "நல்ல வாழ்க்கைத்துணை மற்றும் பிள்ளைகளுக்கான குர்ஆன் துஆ.", "வீட்டில் அமைதிக்கும் நல்ல பிள்ளைகளுக்கும்."),
        "dua_righteous_children" to DuaText("நல்ல சந்ததிக்காக", "என் இறைவா! உன்னிடமிருந்து எனக்குத் தூய சந்ததியை வழங்குவாயாக; நிச்சயமாக நீ பிரார்த்தனையைச் செவியுறுபவன்.", "ஸகரிய்யா (அலை) அவர்களின் துஆ.", "பிள்ளைப் பேறு வேண்டும் குர்ஆன் துஆ."),
        "dua_ibrahim_prayer_family" to DuaText("தொழுகையை நிலைநாட்டுபவர்கள்", "என் இறைவா! என்னையும் என் சந்ததியையும் தொழுகையை நிலைநாட்டுபவர்களாக ஆக்குவாயாக. எங்கள் இறைவா! என் பிரார்த்தனையை ஏற்றுக்கொள்வாயாக. எங்கள் இறைவா! கேள்வி கணக்கு நாளில் என்னையும் என் பெற்றோரையும் இறைநம்பிக்கையாளர்களையும் மன்னிப்பாயாக.", "இப்ராஹீம் (அலை) அவர்கள் தமக்கும் சந்ததிக்கும் கேட்ட துஆ.", "பொதுவாகத் தொழுகையின் இறுதியில் ஓதப்படுகிறது."),
        "dua_newlywed" to DuaText("புதுமணத் தம்பதிக்கு வாழ்த்து", "அல்லாஹ் உனக்குப் பரக்கத் செய்வானாக, உன் மீது பரக்கத் பொழிவானாக, உங்கள் இருவரையும் நன்மையில் இணைத்து வைப்பானாக.", "திருமணம் செய்தவருக்கு வாழ்த்துக் கூறும்போது.", "திருமணத்தின் சுன்னத்தான வாழ்த்து."),
        "dua_before_eating" to DuaText("உண்பதற்கு முன்", "அல்லாஹ்வின் பெயரால். (மறந்துவிட்டால்:) அல்லாஹ்வின் பெயரால், இதன் ஆரம்பத்திலும் இறுதியிலும்.", "உண்பதற்கு முன். மறந்துவிட்டால் இடையில் ஓதுங்கள்.", "பிஸ்மில்லாஹ் கூறுவதால் உணவில் ஷைத்தான் பங்கெடுப்பதில்லை."),
        "dua_after_eating" to DuaText("உண்ட பின்", "என் எந்த ஆற்றலும் சக்தியும் இன்றி இதை எனக்கு உண்ணத் தந்து வழங்கிய அல்லாஹ்வுக்கே எல்லாப் புகழும்.", "உணவை முடித்த பின்.", "இதை ஓதுபவரின் முந்தைய பாவங்கள் மன்னிக்கப்படுகின்றன."),
        "dua_host" to DuaText("விருந்தளிப்பவருக்காக", "யா அல்லாஹ்! நீ அவர்களுக்கு வழங்கியவற்றில் பரக்கத் செய்வாயாக, அவர்களை மன்னித்து அவர்கள் மீது கருணை காட்டுவாயாக.", "ஒருவர் வீட்டில் உண்ட பின் விருந்தளிப்பவருக்காக.", "சுன்னத்தான முறையில் விருந்தளிப்பவருக்கு நன்றி."),
        "dua_breaking_fast" to DuaText("நோன்பு திறக்கும்போது", "தாகம் தீர்ந்தது, நரம்புகள் நனைந்தன, அல்லாஹ் நாடினால் கூலி உறுதியானது.", "இஃப்தார் நேரத்தில்.", "நபி ﷺ நோன்பு திறக்கும்போது இதைக் கூறுவார்கள்."),
        "dua_new_clothes" to DuaText("புதிய ஆடை அணியும்போது", "யா அல்லாஹ்! உனக்கே எல்லாப் புகழும், நீயே இதை எனக்கு அணிவித்தாய். இதன் நன்மையையும் இது எதற்காக உருவாக்கப்பட்டதோ அதன் நன்மையையும் உன்னிடம் கேட்கிறேன்; இதன் தீமையிலிருந்தும் இது எதற்காக உருவாக்கப்பட்டதோ அதன் தீமையிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "புதிய ஆடை அணியும்போது (சட்டை, தலைப்பாகை போன்று ஆடையின் பெயரைக் கூறி).", "நபி ﷺ புதிய ஆடை அணியும்போது இந்த துஆவைக் கேட்பார்கள். (தினமும் ஆடை அணியும் துஆ 'ஆடை அணிதல்' பகுதியில் உள்ளது.)"),
        "dua_rabbana_atina" to DuaText("இம்மை மறுமை நன்மை", "எங்கள் இறைவா! எங்களுக்கு இம்மையிலும் நன்மையை வழங்குவாயாக, மறுமையிலும் நன்மையை வழங்குவாயாக, நரக வேதனையிலிருந்து எங்களைக் காப்பாயாக.", "நபி ﷺ அதிகமாகக் கேட்ட துஆ இது.", "இம்மை மறுமையின் எல்லா நன்மைகளையும் ஒருங்கிணைக்கும் துஆ."),
        "dua_rabbi_zidni_ilma" to DuaText("அறிவில் அதிகரிப்பு", "என் இறைவா! எனக்கு அறிவை அதிகப்படுத்துவாயாக.", "அறிவு அதிகரிப்பதற்காக.", "அறிவு அதிகரிப்பதைத் தவிர வேறெதையும் அதிகம் கேட்கும்படி அல்லாஹ் நபி ﷺ அவர்களுக்குக் கட்டளையிடவில்லை."),
        "dua_musa_sharh_sadr" to DuaText("நெஞ்சை விரிவாக்கும் துஆ (மூஸா அலை)", "என் இறைவா! என் நெஞ்சத்தை எனக்கு விரிவாக்குவாயாக, என் காரியத்தை எனக்கு எளிதாக்குவாயாக, என் நாவிலுள்ள முடிச்சை அவிழ்ப்பாயாக, அவர்கள் என் பேச்சைப் புரிந்துகொள்ள.", "தேர்வு, சொற்பொழிவு அல்லது கடினமான பணிக்கு முன்.", "மூஸா (அலை) அவர்களின் துஆ — மன அமைதியும் பணியில் எளிமையும்."),
        "dua_la_tuzigh" to DuaText("இதயத்தின் உறுதி", "எங்கள் இறைவா! எங்களுக்கு நேர்வழி காட்டிய பின் எங்கள் இதயங்களைத் தடம்புரளச் செய்யாதே, உன்னிடமிருந்து எங்களுக்கு அருளை வழங்குவாயாக; நிச்சயமாக நீயே வாரி வழங்குபவன்.", "நேர்வழியில் உறுதியாக இருப்பதற்காக.", "ஈமானில் உறுதியாக இருக்கும் துஆ."),
        "dua_ya_muqallib" to DuaText("இதயங்களைப் புரட்டுபவனே", "இதயங்களைப் புரட்டுபவனே! என் இதயத்தை உன் மார்க்கத்தில் உறுதிப்படுத்துவாயாக.", "நபி ﷺ அடிக்கடி இந்த துஆவைக் கேட்பார்கள்.", "உம்மு ஸலமா (ரலி) அவர்களின் கூற்றுப்படி நபி ﷺ அதிகம் கேட்ட துஆ."),
        "dua_la_tuakhidhna" to DuaText("சூரா அல்-பகராவின் இறுதி வசனங்கள்", "எங்கள் இறைவா! நாங்கள் மறந்தாலோ தவறிழைத்தாலோ எங்களைப் பிடிக்காதே. எங்கள் இறைவா! எங்களுக்கு முன்னிருந்தோர் மீது சுமத்தியது போன்ற சுமையை எங்கள் மீது சுமத்தாதே. எங்கள் இறைவா! எங்களால் தாங்க முடியாததை எங்கள் மீது சுமத்தாதே. எங்களை மன்னித்து, எங்கள் பாவங்களை மன்னித்து, எங்கள் மீது கருணை காட்டுவாயாக. நீயே எங்கள் பாதுகாவலன்; எனவே நிராகரிக்கும் கூட்டத்திற்கு எதிராக எங்களுக்கு உதவுவாயாக.", "இரவில் தூங்கும் முன் — சூரா அல்-பகராவின் இறுதி இரு வசனங்கள்.", "இரவில் சூரா அல்-பகராவின் இறுதி இரு வசனங்களை ஓதுபவருக்கு அவை போதுமானவையாகும்."),
        "dua_visiting_sick" to DuaText("நோயாளியைச் சந்திக்கும்போது", "மகத்தான அர்ஷின் இறைவனான மகத்தான அல்லாஹ்விடம் உனக்குக் குணமளிக்கும்படி கேட்கிறேன்.", "நோயாளியைச் சந்திக்கும்போது ஏழு முறை.", "மரண நேரம் வராவிட்டால் அல்லாஹ் அவருக்குக் குணமளிக்கிறான்."),
        "dua_ruqyah_pain" to DuaText("உடல் வலிக்காக", "நான் உணரும் மற்றும் அஞ்சும் வேதனையின் தீங்கிலிருந்து அல்லாஹ்விடமும் அவனுடைய ஆற்றலிடமும் பாதுகாப்புத் தேடுகிறேன்.", "வலியுள்ள இடத்தில் கை வைத்து மூன்று முறை பிஸ்மில்லாஹ், பின் ஏழு முறை இந்த துஆ.", "நபி ﷺ உஸ்மான் பின் அபில் ஆஸ் (ரலி) அவர்களுக்கு வலிக்காகக் கற்றுத்தந்தார்கள்."),
        "dua_ruqyah_nabawi" to DuaText("நோயாளிக்கான நபிவழி ருக்யா", "யா அல்லாஹ், மனிதர்களின் இறைவனே! துன்பத்தை நீக்கி குணமளிப்பாயாக; நீயே குணமளிப்பவன்; உன் குணமளித்தலைத் தவிர வேறு குணமில்லை; எந்த நோயையும் விட்டுவைக்காத குணத்தை அளிப்பாயாக.", "நோயாளியின் மீது கையைத் தடவியவாறு.", "நபி ﷺ தம் குடும்பத்தினரில் நோயுற்றோரைச் சந்திக்கும்போது இதை ஓதுவார்கள்."),
        "dua_kalimat_tammat" to DuaText("பரிபூரண வார்த்தைகளின் பாதுகாப்பு", "அல்லாஹ் படைத்தவற்றின் தீங்கிலிருந்து அவனுடைய பரிபூரண வார்த்தைகளைக் கொண்டு பாதுகாப்புத் தேடுகிறேன்.", "ஓரிடத்தில் தங்கும்போது அல்லது மாலையில்.", "ஓரிடத்தில் இறங்கி இதை ஓதுபவருக்கு அங்கிருந்து புறப்படும் வரை எதுவும் தீங்கிழைக்காது."),
        "dua_evil_eye" to DuaText("குழந்தைகளின் பாதுகாப்பு (கண் திருஷ்டி)", "ஒவ்வொரு ஷைத்தானிடமிருந்தும் விஷ ஜந்துவிடமிருந்தும், தீங்கிழைக்கும் ஒவ்வொரு கண்ணிடமிருந்தும் அல்லாஹ்வின் பரிபூரண வார்த்தைகளைக் கொண்டு உங்கள் இருவருக்கும் பாதுகாப்புத் தேடுகிறேன்.", "நபி ﷺ ஹஸன், ஹுஸைன் (ரலி) மீது இதை ஓதி ஊதுவார்கள்.", "குழந்தைகளைக் கண் திருஷ்டி மற்றும் தீங்கிலிருந்து காக்கும் சுன்னத்தான துஆ (ஒரு குழந்தைக்கு 'உயீதுக')."),
        "dua_seeing_afflicted" to DuaText("ஒருவரைத் துன்பத்தில் காணும்போது", "உன்னைச் சோதித்ததிலிருந்து என்னைப் பாதுகாத்து, அவனுடைய படைப்புகளில் பலவற்றை விட என்னைச் சிறப்பித்த அல்லாஹ்வுக்கே எல்லாப் புகழும்.", "ஒருவரைத் துன்பத்தில் காணும்போது (மனதிற்குள் ஓதுங்கள்).", "ஓதுபவர் அந்தத் துன்பத்திலிருந்து பாதுகாக்கப்படுவார்."),
        "dua_istikhara" to DuaText("இஸ்திகாரா தொழுகை", "யா அல்லாஹ்! உன் அறிவைக் கொண்டு உன்னிடம் நன்மையைத் தேடுகிறேன், உன் ஆற்றலைக் கொண்டு சக்தியைக் கேட்கிறேன், உன் மகத்தான அருளை உன்னிடம் வேண்டுகிறேன். நீ ஆற்றலுடையவன், நான் ஆற்றலற்றவன்; நீ அறிந்தவன், நான் அறியாதவன்; நீ மறைவானவற்றை நன்கறிந்தவன். யா அல்லாஹ்! இந்தக் காரியம் (உங்கள் காரியத்தை மனதில் கொண்டு வாருங்கள்) என் மார்க்கத்திற்கும், வாழ்க்கைக்கும், முடிவிற்கும் நல்லது என உன் அறிவில் இருந்தால், அதை எனக்கு விதித்து, எளிதாக்கி, அதில் பரக்கத் செய்வாயாக. இந்தக் காரியம் என் மார்க்கத்திற்கும், வாழ்க்கைக்கும், முடிவிற்கும் தீயது என உன் அறிவில் இருந்தால், அதை என்னை விட்டும் என்னை அதை விட்டும் திருப்பிவிடுவாயாக; நன்மை எங்கிருந்தாலும் அதை எனக்கு விதித்து, பின் அதில் என்னைத் திருப்தியடையச் செய்வாயாக.", "அனுமதிக்கப்பட்ட காரியத்தில் நன்மையைத் தேட இரண்டு ரக்அத் நஃபில் தொழுகைக்குப் பின்.", "நபி ﷺ தோழர்களுக்கு எல்லா விஷயங்களிலும் இஸ்திகாராவை குர்ஆன் சூராவைப் போல் கற்றுத்தருவார்கள்."),
        "dua_allahumma_bika_asbahna" to DuaText("அல்லாஹும்ம பிக அஸ்பஹ்னா", "யா அல்லாஹ்! உன்னைக் கொண்டே நாங்கள் காலையை அடைந்தோம், உன்னைக் கொண்டே மாலையை அடைந்தோம்; உன்னைக் கொண்டே வாழ்கிறோம், மரணிக்கிறோம்; உன்னிடமே மீண்டும் எழுப்பப்படுதல் உள்ளது.", "காலையில்.", "நபி ﷺ தோழர்களுக்குக் காலை மாலையில் இதைக் கற்றுத்தருவார்கள்."),
        "dua_allahumma_bika_amsayna" to DuaText("அல்லாஹும்ம பிக அம்ஸைனா", "யா அல்லாஹ்! உன்னைக் கொண்டே நாங்கள் மாலையை அடைந்தோம், உன்னைக் கொண்டே காலையை அடைந்தோம்; உன்னைக் கொண்டே வாழ்கிறோம், மரணிக்கிறோம்; உன்னிடமே திரும்புதல் உள்ளது.", "மாலையில்.", "நபி ﷺ தோழர்களுக்குக் காலை மாலையில் இதைக் கற்றுத்தருவார்கள்."),
        "dua_afiyah_morning" to DuaText("ஆஃபியத் (நலம்) துஆ", "யா அல்லாஹ்! இம்மையிலும் மறுமையிலும் மன்னிப்பையும் நலத்தையும் உன்னிடம் கேட்கிறேன்.", "நபி ﷺ காலை மாலையில் இந்த துஆவை ஒருபோதும் விட்டதில்லை.", "நலத்தை விடச் சிறந்த எதுவும் யாருக்கும் வழங்கப்படவில்லை."),
        "dua_afini_fi_badani" to DuaText("உடல், செவி, பார்வையின் நலம்", "யா அல்லாஹ்! என் உடலில் நலம் தருவாயாக, என் செவிப்புலனில் நலம் தருவாயாக, என் பார்வையில் நலம் தருவாயாக. உன்னைத் தவிர வணக்கத்திற்குரியவன் இல்லை.", "காலையும் மாலையும் மும்முறை.", "உடல்நலம் மற்றும் புலன்களைப் பாதுகாக்கும் துஆ."),
        "dua_ya_hayyu_aslih" to DuaText("என் காரியங்கள் அனைத்தையும் சீராக்கு", "என்றும் உயிருள்ளவனே, நிலைநிறுத்துபவனே! உன் அருளைக் கொண்டு உதவி தேடுகிறேன்; என் காரியங்கள் அனைத்தையும் சீராக்குவாயாக, கண் இமைக்கும் நேரம் கூட என்னை என் மனதிடம் ஒப்படைத்துவிடாதே.", "நபி ﷺ ஃபாத்திமா (ரலி) அவர்களுக்குக் காலை மாலையில் ஓதும்படி அறிவுறுத்தினார்கள்.", "ஒவ்வொரு காரியத்திலும் அல்லாஹ்வின் உதவியை வேண்டுதல்."),
        "dua_subhanallah_adada_khalqihi" to DuaText("ஜுவைரிய்யா (ரலி) அவர்களின் தஸ்பீஹ்", "அல்லாஹ் தூயவன், புகழ் அவனுக்கே — அவனுடைய படைப்புகளின் எண்ணிக்கை அளவு, அவனுடைய திருப்திக்கேற்ப, அவனுடைய அர்ஷின் எடை அளவு, அவனுடைய வார்த்தைகளின் மை அளவு.", "காலையில் மூன்று முறை — பல மணி நேர திக்ரை விடக் கனமானது.", "இந்த நான்கு வாக்கியங்களை மூன்று முறை கூறுவது காலை முதல் முற்பகல் வரையிலான திக்ரை விட எடையில் கனமானது."),
        "dua_salawat" to DuaText("ஸலவாத் இப்ராஹீமிய்யா", "யா அல்லாஹ்! இப்ராஹீம் (அலை) மீதும் இப்ராஹீமின் குடும்பத்தார் மீதும் நீ அருள் புரிந்தது போல் முஹம்மத் ﷺ மீதும் முஹம்மதின் குடும்பத்தார் மீதும் அருள் புரிவாயாக; நிச்சயமாக நீ புகழுக்குரியவன், மகிமைமிக்கவன். யா அல்லாஹ்! இப்ராஹீம் (அலை) மீதும் இப்ராஹீமின் குடும்பத்தார் மீதும் நீ பரக்கத் செய்தது போல் முஹம்மத் ﷺ மீதும் முஹம்மதின் குடும்பத்தார் மீதும் பரக்கத் செய்வாயாக; நிச்சயமாக நீ புகழுக்குரியவன், மகிமைமிக்கவன்.", "தொழுகையிலும் எல்லா நேரங்களிலும் நபி ﷺ மீது ஸலவாத்.", "ஒருமுறை ஸலவாத் கூறுபவர் மீது அல்லாஹ் பத்து அருள்களைப் பொழிகிறான் (முஸ்லிம் 408)."),
        "dua_wudu_after" to DuaText("உளூவுக்குப் பின்", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணை இல்லை என்றும், முஹம்மத் ﷺ அவனுடைய அடியாரும் தூதருமாவார் என்றும் சாட்சி கூறுகிறேன். யா அல்லாஹ்! என்னைப் பாவமன்னிப்புக் கோருவோரிலும் தூய்மையானோரிலும் ஆக்குவாயாக.", "உளூவை முடித்த பின்.", "சொர்க்கத்தின் எட்டு வாசல்களும் திறக்கப்படுகின்றன, விரும்பிய வாசல் வழியே நுழையலாம்."),
        "dua_wudu_before" to DuaText("உளூவுக்கு முன்", "அல்லாஹ்வின் பெயரால்.", "உளூவைத் தொடங்கும்போது.", "உளூவில் அல்லாஹ்வின் பெயரைக் கூறாதவரின் உளூ (பூரணமாக) இல்லை."),
        "dua_istiftah" to DuaText("ஸனா (தொழுகையின் ஆரம்ப துஆ)", "யா அல்லாஹ்! உன் புகழுடன் நீ தூயவன், உன் பெயர் பாக்கியமிக்கது, உன் மகிமை உயர்ந்தது, உன்னைத் தவிர வணக்கத்திற்குரியவன் இல்லை.", "தொழுகையைத் தொடங்கும்போது, தக்பீர் தஹ்ரீமாவுக்கு உடனே பின்.", "தொழுகையின் சுன்னத்தான ஆரம்ப துஆ."),
        "dua_ruku" to DuaText("ருகூவில்", "மகத்தான என் இறைவன் தூயவன்.", "ருகூவில் குறைந்தது மூன்று முறை.", "ருகூவின் சுன்னத்தான தஸ்பீஹ்."),
        "dua_sujood" to DuaText("ஸஜ்தாவில்", "மிக உயர்ந்த என் இறைவன் தூயவன்.", "ஸஜ்தாவில் குறைந்தது மூன்று முறை.", "அடியான் ஸஜ்தாவில் தன் இறைவனுக்கு மிக நெருக்கமாக இருக்கிறான் (முஸ்லிம் 482)."),
        "dua_rising_ruku" to DuaText("ருகூவிலிருந்து எழும்போது", "தன்னைப் புகழ்பவரை அல்லாஹ் செவியுற்றான். எங்கள் இறைவா! உனக்கே எல்லாப் புகழும்.", "ருகூவிலிருந்து எழும்போதும் நேராக நிற்கும்போதும்.", "யாருடைய 'ரப்பனா வ லகல் ஹம்த்' வானவர்களின் கூற்றுடன் ஒத்துப்போகிறதோ அவரின் முந்தைய பாவங்கள் மன்னிக்கப்படும்."),
        "dua_between_sajdas" to DuaText("இரு ஸஜ்தாக்களுக்கு இடையே", "என் இறைவா! என்னை மன்னிப்பாயாக, என் இறைவா! என்னை மன்னிப்பாயாக.", "இரு ஸஜ்தாக்களுக்கு இடையே அமர்ந்திருக்கும்போது.", "ஜல்ஸாவின் சுன்னத்தான துஆ."),
        "dua_before_salam_four" to DuaText("நான்கு விஷயங்களிலிருந்து பாதுகாப்பு (ஸலாமுக்கு முன்)", "யா அல்லாஹ்! நரக வேதனையிலிருந்தும், கப்ர் வேதனையிலிருந்தும், வாழ்வு மற்றும் மரணத்தின் சோதனையிலிருந்தும், மஸீஹ் தஜ்ஜாலின் சோதனையின் தீங்கிலிருந்தும் உன்னிடம் பாதுகாப்புத் தேடுகிறேன்.", "இறுதி அத்தஹிய்யாத் மற்றும் ஸலவாத்துக்குப் பின், ஸலாமுக்கு முன்.", "இந்த நான்கிலிருந்தும் பாதுகாப்புத் தேடும்படி நபி ﷺ கட்டளையிட்டார்கள்."),
        "dua_qunoot_witr" to DuaText("வித்ரில் குனூத்", "யா அல்லாஹ்! நீ நேர்வழி காட்டியவர்களுடன் எனக்கும் நேர்வழி காட்டுவாயாக; நீ நலமளித்தவர்களுடன் எனக்கும் நலமளிப்பாயாக; நீ பொறுப்பேற்றவர்களுடன் என்னையும் பொறுப்பேற்பாயாக; நீ வழங்கியதில் எனக்குப் பரக்கத் செய்வாயாக; நீ விதித்ததன் தீங்கிலிருந்து என்னைக் காப்பாயாக. நிச்சயமாக நீயே தீர்ப்பளிக்கிறாய், உனக்கு எதிராகத் தீர்ப்பளிக்கப்படுவதில்லை; நீ நேசித்தவன் இழிவடைய மாட்டான். எங்கள் இறைவா! நீ பாக்கியமிக்கவன், உயர்ந்தவன்.", "வித்ர் தொழுகையில் — நபி ﷺ ஹஸன் பின் அலீ (ரலி) அவர்களுக்குக் கற்றுத்தந்தார்கள்.", "வித்ரின் சுன்னத்தான குனூத். (ஹனஃபிகளிடம் 'அல்லாஹும்ம இன்னா நஸ்தஈனுக' என்பதும் பிரபலமானது.)"),
        "dua_qunoot_hanafi" to DuaText("குனூத் (அல்லாஹும்ம இன்னா நஸ்தஈனுக)", "யா அல்லாஹ்! நாங்கள் உன்னிடம் உதவியும் மன்னிப்பும் தேடுகிறோம், உன்னை நம்புகிறோம், உன் மீது நம்பிக்கை வைக்கிறோம், உன்னை அழகிய முறையில் புகழ்கிறோம், உனக்கு நன்றி செலுத்துகிறோம், நன்றி மறக்கமாட்டோம், உனக்கு மாறு செய்பவரை விட்டுவிடுகிறோம். யா அல்லாஹ்! உன்னையே வணங்குகிறோம், உனக்காகவே தொழுகிறோம், ஸஜ்தா செய்கிறோம், உன்னை நோக்கியே விரைகிறோம், உன் அருளை ஆதரவு வைக்கிறோம், உன் வேதனையை அஞ்சுகிறோம்; நிச்சயமாக உன் வேதனை நிராகரிப்பாளர்களை அடையக்கூடியது.", "வித்ரில் — ஹனஃபிகளின் நடைமுறை.", "உமர் (ரலி) அவர்களிடமிருந்து குனூத்தில் அறிவிக்கப்பட்டது."),
        "dua_sleep_aslamtu" to DuaText("தூங்கும் முன் இறுதி வார்த்தைகள்", "யா அல்லாஹ்! என்னை உன்னிடம் ஒப்படைத்தேன், என் காரியத்தை உன்னிடம் விட்டுவிட்டேன், என் முதுகை உன் பாதுகாப்பில் சாய்த்தேன், உன் மீதான ஆசையுடனும் அச்சத்துடனும். உன்னை விட்டு ஒதுங்கவோ தப்பிக்கவோ உன்னிடமே அன்றி வேறு இடமில்லை. நீ இறக்கிய வேதத்தையும் நீ அனுப்பிய நபியையும் நம்பினேன்.", "உளூ செய்து வலது பக்கம் படுத்து — மிக இறுதியான வார்த்தைகள்.", "அன்றிரவே இறந்தால் இஸ்லாமிய இயற்கை நெறியில் இறப்பார்."),
        "dua_waking_night" to DuaText("இரவில் விழித்தால்", "அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அவன் தனித்தவன், அவனுக்கு இணை இல்லை; ஆட்சியும் புகழும் அவனுக்கே, அவன் எல்லாவற்றின் மீதும் ஆற்றலுடையவன். எல்லாப் புகழும் அல்லாஹ்வுக்கே, அல்லாஹ் தூயவன், அல்லாஹ்வைத் தவிர வணக்கத்திற்குரியவன் இல்லை, அல்லாஹ் மிகப் பெரியவன், அல்லாஹ்வைக் கொண்டே அன்றி ஆற்றலும் சக்தியும் இல்லை. யா அல்லாஹ்! என்னை மன்னிப்பாயாக.", "இரவில் விழித்தால்.", "துஆ ஏற்கப்படும்; உளூ செய்து தொழுதால் தொழுகையும் ஏற்கப்படும்."),
        "dua_hamm_ibn_masud" to DuaText("துக்கத்தின் துஆ (இப்னு மஸ்ஊத்)", "யா அல்லாஹ்! நான் உன் அடியான், உன் அடியானின் மகன், உன் அடியாளின் மகன். என் நெற்றி உன் கையில் உள்ளது, உன் கட்டளை என் மீது நிறைவேறுகிறது, என் விஷயத்தில் உன் தீர்ப்பு நீதியானது. நீ உனக்குச் சூட்டிக்கொண்ட, அல்லது உன் வேதத்தில் இறக்கிய, அல்லது உன் படைப்புகளில் எவருக்கேனும் கற்றுத்தந்த, அல்லது உன்னிடம் மறைவான அறிவில் பாதுகாத்து வைத்த உன்னுடைய ஒவ்வொரு பெயரைக் கொண்டும் உன்னிடம் கேட்கிறேன் — குர்ஆனை என் இதயத்தின் வசந்தமாகவும், என் நெஞ்சின் ஒளியாகவும், என் துக்கத்தின் நிவாரணமாகவும், என் கவலையைப் போக்குவதாகவும் ஆக்குவாயாக.", "துக்கம் மற்றும் கவலையில் — அல்லாஹ் துக்கத்தை மகிழ்ச்சியாக மாற்றுகிறான்.", "அல்லாஹ் அவரின் கவலையையும் துக்கத்தையும் நீக்கி மகிழ்ச்சியை வழங்குகிறான்."),
        "dua_difficulty_sahl" to DuaText("ஒரு காரியம் கடினமாக இருக்கும்போது", "யா அல்லாஹ்! நீ எளிதாக்கியதைத் தவிர எதுவும் எளிதானதல்ல; நீ நாடினால் கடினமானதை எளிதாக்குகிறாய்.", "ஒரு காரியம் கடினமாகத் தோன்றும்போது.", "தேர்வுகளிலும் கடினமான காரியங்களிலும் எளிமை."),
        "dua_musibah" to DuaText("துன்பத்தின் போது (இஸ்திர்ஜாஃ)", "நாங்கள் அல்லாஹ்வுக்கே உரியவர்கள், அவனிடமே திரும்புபவர்கள். யா அல்லாஹ்! என் துன்பத்தில் எனக்குக் கூலி வழங்கி, இதை விடச் சிறந்த பகரத்தைத் தருவாயாக.", "எந்த இழப்பு அல்லது துன்பத்தின் போதும்.", "அல்லாஹ் நிச்சயமாகச் சிறந்த பகரம் தருகிறான் — உம்மு ஸலமா (ரலி) அவர்களுக்கு நபி ﷺ கிடைத்தார்கள்."),
        "dua_debt" to DuaText("கடனிலிருந்து விடுபட", "யா அல்லாஹ்! உன் ஹலாலைக் கொண்டு ஹராமிலிருந்து என்னைக் காத்து எனக்குப் போதுமானதாக்குவாயாக; உன் அருளால் உன்னைத் தவிர மற்றவர்களின் தேவையற்றவனாக என்னை ஆக்குவாயாக.", "கடனை அடைப்பதற்கு — அலீ (ரலி) கற்றுத்தந்தது.", "மலையளவு கடன் இருந்தாலும் அல்லாஹ் அதை அடைத்துவிடுவான்."),
        "dua_anger" to DuaText("கோபத்தின் போது", "விரட்டப்பட்ட ஷைத்தானிடமிருந்து அல்லாஹ்விடம் பாதுகாப்புத் தேடுகிறேன்.", "கோபம் வரும்போது.", "நபி ﷺ கூறினார்கள்: இதைக் கூறினால் அவருடைய கோபம் போய்விடும்."),
        "dua_waswasa" to DuaText("ஈமானில் ஊசலாட்டத்திற்கு எதிராக", "அல்லாஹ்வையும் அவனுடைய தூதர்களையும் நம்பினேன்.", "ஈமான் பற்றி ஷைத்தானிய ஊசலாட்டம் வரும்போது.", "ஊசலாட்டம் வந்தால் இதைக் கூறி நிறுத்திக்கொள்ளுங்கள் (அஊது பில்லாஹ்வும் ஓதுங்கள்)."),
        "dua_travel_full" to DuaText("முழுமையான பயண துஆ", "யா அல்லாஹ்! இந்தப் பயணத்தில் நன்மையையும் இறையச்சத்தையும், நீ விரும்பும் செயல்களையும் உன்னிடம் கேட்கிறோம். யா அல்லாஹ்! இந்தப் பயணத்தை எங்களுக்கு எளிதாக்கி அதன் தூரத்தைச் சுருக்குவாயாக. யா அல்லாஹ்! நீயே பயணத்தில் தோழன், குடும்பத்தின் பாதுகாவலன்.", "பயணம் புறப்படும்போது, 'ஸுப்ஹானல்லதீ ஸக்கர' என்பதற்குப் பின்.", "முழுமையான சுன்னத்தான பயண துஆ."),
        "dua_return_travel" to DuaText("பயணத்திலிருந்து திரும்பும்போது", "நாங்கள் திரும்புபவர்கள், பாவமன்னிப்புக் கோருபவர்கள், வணங்குபவர்கள், எங்கள் இறைவனைப் புகழ்பவர்கள்.", "பயணத்திலிருந்து திரும்பும்போது.", "நபி ﷺ பயணத்திலிருந்து திரும்பும்போது இதைக் கூறுவார்கள்."),
        "dua_farewell_traveller" to DuaText("பயணிக்கு விடைகொடுத்தல்", "உன் மார்க்கத்தையும், உன் அமானிதத்தையும், உன் செயல்களின் முடிவையும் அல்லாஹ்விடம் ஒப்படைக்கிறேன்.", "பயணிக்கு விடைகொடுக்கும்போது.", "அல்லாஹ்விடம் ஒப்படைக்கப்பட்டது வீணாவதில்லை."),
        "dua_entering_town" to DuaText("ஓரிடத்தில் தங்கும்போது", "அல்லாஹ் படைத்த அனைத்தின் தீங்கிலிருந்தும் அவனுடைய பரிபூரண வார்த்தைகளைக் கொண்டு பாதுகாப்புத் தேடுகிறேன்.", "ஓரிடத்தில் தங்கும்போது அல்லது புதிய ஊருக்கு வந்தடையும்போது.", "அங்கிருந்து புறப்படும் வரை எதுவும் தீங்கிழைக்காது."),
        "dua_boarding_ship" to DuaText("கப்பல்/வாகனத்தில் ஏறும்போது", "அல்லாஹ்வின் பெயராலேயே இதன் ஓட்டமும் நிற்றலும்; நிச்சயமாக என் இறைவன் மன்னிப்பவன், கருணையாளன்.", "கப்பல் அல்லது வாகனத்தில் ஏறும்போது — நூஹ் (அலை) அவர்களின் கூற்று.", "குர்ஆன் வசனம் — நூஹ் (அலை) அவர்களின் கப்பல் துஆ."),
        "dua_istighfar_hayyul_qayyum" to DuaText("ஹய்யுல் கய்யூமுடன் இஸ்திஃக்ஃபார்", "என்றும் உயிருள்ளவனும் நிலைநிறுத்துபவனுமான, தன்னைத் தவிர வணக்கத்திற்குரியவன் இல்லாத அல்லாஹ்விடம் பாவமன்னிப்புக் கோருகிறேன், அவனிடமே மீள்கிறேன்.", "பாவமன்னிப்புக்காக.", "போர்க்களத்திலிருந்து ஓடியிருந்தாலும் பாவங்கள் மன்னிக்கப்படும்."),
        "dua_rabbighfir_warham" to DuaText("ரப்பிஃக்ஃபிர் வர்ஹம்", "என் இறைவா! மன்னித்துக் கருணை காட்டுவாயாக, நீயே கருணை காட்டுவோரில் மிகச் சிறந்தவன்.", "குர்ஆன் துஆ — மன்னிப்பும் அருளும்.", "சூரா அல்-முஃமினூனின் இறுதி வசனம்."),
        "dua_majlis_kaffarah" to DuaText("சபையின் பரிகாரம்", "யா அல்லாஹ்! உன் புகழுடன் நீ தூயவன். உன்னைத் தவிர வணக்கத்திற்குரியவன் இல்லை என்று சாட்சி கூறுகிறேன். உன்னிடம் பாவமன்னிப்புக் கோருகிறேன், உன்னிடமே மீள்கிறேன்.", "சபை/அமர்விலிருந்து எழும்போது.", "சபையில் நடந்த தவறான பேச்சுகளுக்குப் பரிகாரமாகிறது."),
        "dua_jami_forgiveness" to DuaText("விரிவான மன்னிப்பு", "யா அல்லாஹ்! என் தவறையும், என் அறியாமையையும், என் காரியங்களில் நான் செய்த வரம்பு மீறலையும், என்னை விட நீ நன்கறிந்த அனைத்தையும் மன்னிப்பாயாக.", "நபி ﷺ அவர்களின் விரிவான துஆ.", "நபி ﷺ இந்த துஆவைக் கேட்பார்கள்."),
        "dua_parents_nuh" to DuaText("பெற்றோருக்காக நூஹ் (அலை) அவர்களின் துஆ", "என் இறைவா! என்னையும், என் பெற்றோரையும், இறைநம்பிக்கையுடன் என் வீட்டில் நுழைந்தவரையும், இறைநம்பிக்கையுள்ள ஆண்களையும் பெண்களையும் மன்னிப்பாயாக.", "பெற்றோருக்காகவும் இறைநம்பிக்கையாளர்களுக்காகவும்.", "நூஹ் (அலை) அவர்களின் துஆ."),
        "dua_shukr_parents" to DuaText("பெற்றோருக்கான அருளுக்கு நன்றியும் நல்ல சந்ததியும்", "என் இறைவா! என் மீதும் என் பெற்றோர் மீதும் நீ செய்த அருளுக்கு நன்றி செலுத்தவும், நீ விரும்பும் நற்செயல்களைச் செய்யவும் எனக்கு அருள் புரிவாயாக; என் சந்ததியையும் நல்லவர்களாக்குவாயாக. நான் உன்னிடம் மீள்கிறேன், நான் முஸ்லிம்களில் ஒருவன்.", "நாற்பது வயதின் குர்ஆன் துஆ.", "நன்றி, நற்செயல், சந்ததியின் சீர்திருத்தம் — அனைத்தும் ஒரே துஆவில்."),
        "dua_intimacy" to DuaText("தாம்பத்திய உறவுக்கு முன்", "அல்லாஹ்வின் பெயரால். யா அல்லாஹ்! எங்களை ஷைத்தானை விட்டும் தூரமாக்குவாயாக, நீ எங்களுக்கு வழங்கும் (குழந்தையையும்) ஷைத்தானை விட்டும் தூரமாக்குவாயாக.", "கணவன் மனைவி உறவுக்கு முன்.", "குழந்தை விதிக்கப்பட்டால் ஷைத்தான் அதற்கு ஒருபோதும் தீங்கிழைக்க மாட்டான்."),
        "dua_ibrahim_children_protection" to DuaText("வீடு மற்றும் பிள்ளைகளின் பாதுகாப்பு", "என் இறைவா! இந்த நகரத்தைப் பாதுகாப்பானதாக்குவாயாக, என்னையும் என் பிள்ளைகளையும் சிலைகளை வணங்குவதிலிருந்து தூரமாக்குவாயாக.", "இப்ராஹீம் (அலை) அவர்களின் துஆ — நகரம் மற்றும் பிள்ளைகளின் பாதுகாப்பு.", "ஏகத்துவத்தில் நிலைத்திருக்கும் துஆ."),
        "dua_drinking_milk" to DuaText("பால் அருந்தும்போது", "யா அல்லாஹ்! இதில் எங்களுக்குப் பரக்கத் செய்து, இதை எங்களுக்கு அதிகப்படுத்துவாயாக.", "பால் அருந்தும்போது.", "பால் உணவுக்கும் பானத்துக்கும் போதுமானது."),
        "dua_iftar_host" to DuaText("ஒருவர் வீட்டில் நோன்பு திறக்கும்போது", "உங்களிடம் நோன்பாளிகள் நோன்பு திறக்கட்டும், நல்லோர் உங்கள் உணவை உண்ணட்டும், வானவர்கள் உங்களுக்காகப் பிரார்த்திக்கட்டும்.", "ஒருவர் வீட்டில் நோன்பு திறக்கும்போது.", "விருந்தளிப்பவருக்கான நபி ﷺ அவர்களின் துஆ."),
        "dua_seeing_first_fruit" to DuaText("பருவத்தின் முதல் பழத்தைக் கண்டால்", "யா அல்லாஹ்! எங்கள் பழங்களிலும், எங்கள் நகரத்திலும், எங்கள் ஸாஃ மற்றும் முத் (அளவைகளிலும்) பரக்கத் செய்வாயாக.", "பருவத்தின் முதல் பழத்தைக் கண்டதும்.", "வாழ்வாதாரம் மற்றும் நகரத்தில் பரக்கத்திற்கான துஆ."),
        "dua_good_news" to DuaText("நற்செய்தி கிடைக்கும்போது", "எவனுடைய அருளால் நல்லவை நிறைவடைகின்றனவோ அந்த அல்லாஹ்வுக்கே எல்லாப் புகழும்.", "மகிழ்ச்சியான செய்தி கிடைக்கும்போது (நன்றி ஸஜ்தாவும்).", "நபி ﷺ விரும்பியதைக் கண்டால் இதைக் கூறுவார்கள்."),
        "dua_looking_mirror" to DuaText("கண்ணாடி பார்க்கும்போது", "யா அல்லாஹ்! நீ என் தோற்றத்தை அழகாக்கியது போல் என் குணத்தையும் அழகாக்குவாயாக.", "கண்ணாடி பார்க்கும்போது.", "நபி ﷺ இந்த துஆவைக் கேட்பார்கள் (கண்ணாடி நிபந்தனையின்றியும் உறுதியானது)."),
        "dua_rabbana_taqabbal" to DuaText("செயல்களின் ஏற்பு", "எங்கள் இறைவா! எங்களிடமிருந்து ஏற்றுக்கொள்வாயாக; நிச்சயமாக நீ செவியுறுபவன், அறிந்தவன். எங்கள் தவ்பாவை ஏற்றுக்கொள்வாயாக; நிச்சயமாக நீ தவ்பாவை ஏற்பவன், கருணையாளன்.", "இப்ராஹீம், இஸ்மாயீல் (அலை) கஅபாவைக் கட்டும்போது கேட்டது.", "ஒவ்வொரு நற்செயலுக்குப் பின்னும் ஏற்பு துஆ."),
    )
}
